const D = { density:.5, energy:.6, speed:1, scale:1, hue:220, x:.5, y:.45, lines:.6, style:'night', act:'reveal', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const style=P.style;
const night=style==='night', parch=style==='parchment', blue=style==='blueprint', spec=style==='spectral';
const hue=md(P.hue,360);
const dens=clp(P.density,0,1);
const en=clp(P.energy,0,1);
const spd=P.speed;

// star count from density (FIRST poke param — obvious structural change)
const NSTAR=Math.round(90+dens*180);
// constellation richness from lines param
const NCON=Math.round(3+clp(P.lines,0,1)*7);

function temp(t){t=clp(t,0,1); // spectral: hot-blue -> white -> yellow -> orange -> red
  if(t<.3){const k=t/.3;return[md(222-8*k,360),70-40*k,100];}
  if(t<.6){const k=(t-.3)/.3;return[md(214+ (46*k),360),8+52*k,100];}
  const k=(t-.6)/.4;return[md(50-40*k,360),60+30*k,100-14*k];
}

// ---- build seed/density-deterministic sky (stars + constellations + figure) ----
const key=P.seed+'|'+NSTAR+'|'+NCON+'|'+style;
if(S.key!==key){
  S.key=key; S.seedUsed=P.seed;
  const stars=[];
  for(let s=0;s<NSTAR;s++){
    const mag=Math.pow(fr(s*1.7+3),2.1);              // few bright, many faint
    stars.push({ x:fr(s*3.1+1), y:fr(s*5.7+2), mag,
      b: 30+70*(1-mag), sz:0.4+2.4*(1-mag),
      tr:0.5+2.8*fr(s*7.3+4), tp:fr(s*2.9+5)*TAU,
      tmp:fr(s*4.4+6) });
  }
  // pick bright anchor stars, weave each constellation as a short path/tree
  const bright=stars.map((v,i)=>i).sort((a,b)=>stars[a].mag-stars[b].mag).slice(0,Math.min(stars.length,NCON*5));
  const segs=[]; const cons=[];
  let bi=0;
  for(let c=0;c<NCON && bi<bright.length;c++){
    const len=3+Math.floor(fr(c*11.1+9)*4);
    const idxs=[]; let cur=bright[bi++]; idxs.push(cur);
    for(let l=1;l<len && bi<bright.length;l++){
      // connect to nearest unused-ish bright star for a plausible figure
      let best=-1,bd=1e9;
      for(let q=bi;q<Math.min(bi+6,bright.length);q++){
        const o=bright[q]; const dd=Math.hypot(stars[o].x-stars[cur].x,stars[o].y-stars[cur].y);
        if(dd<bd){bd=dd;best=q;}
      }
      if(best<0)break; const nx=bright[best]; bright[best]=bright[bi]; bright[bi]=nx; bi++;
      segs.push({a:cur,b:nx,c}); cur=nx; idxs.push(cur);
    }
    // constellation bounds for the hinted mythic figure
    let mnx=1,mny=1,mxx=0,mxy=0;
    idxs.forEach(o=>{mnx=Math.min(mnx,stars[o].x);mny=Math.min(mny,stars[o].y);mxx=Math.max(mxx,stars[o].x);mxy=Math.max(mxy,stars[o].y);});
    cons.push({idxs,cx:(mnx+mxx)/2,cy:(mny+mxy)/2,r:Math.max(mxx-mnx,mxy-mny)/2+0.04});
  }
  S.stars=stars; S.segs=segs; S.cons=cons; S.nseg=segs.length;
  S.bgKey=null; // force bg rebuild
}
// ---- cached backdrop (gradient + nebula), keyed on size+style+seed ----
const bgKey=W+'x'+Hh+'|'+style+'|'+P.seed;
if(S.bgKey!==bgKey){
  S.bgKey=bgKey;
  const g=createGraphics(W,Hh); g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  if(parch){ g.background(40,16,90);
    for(let i=0;i<2600;i++){ const x=fr(i*1.3+11)*W,y=fr(i*2.1+12)*Hh; g.fill(32,40,55,4+8*fr(i*0.7)); g.rect(x,y,1.4,1.4);} // foxing grain
    g.fill(34,30,40,10); for(let r=0;r<5;r++){g.ellipse(fr(r*9.1+21)*W,fr(r*4.3+22)*Hh,u*0.4,u*0.34);} }
  else if(blue){ g.background(220,72,16);
    g.stroke(200,50,90,10); g.strokeWeight(0.7);
    const st=u*0.08; for(let x=0;x<=W;x+=st)g.line(x,0,x,Hh); for(let y=0;y<=Hh;y+=st)g.line(0,y,W,y); g.noStroke(); }
  else { // night / spectral deep sky gradient + nebula
    const top=night?[235,80,12]:[250,70,9], bot=night?[220,55,3]:[275,60,4];
    for(let y=0;y<Hh;y+=2){ const t=y/Hh; g.fill(md(top[0]+(bot[0]-top[0])*t,360),top[1]+(bot[1]-top[1])*t,top[2]+(bot[2]-top[2])*t); g.rect(0,y,W,2);}
    for(let n=0;n<4;n++){ const nx=fr(n*6.1+31)*W,ny=fr(n*3.7+32)*Hh,nr=u*(0.2+0.3*fr(n*2.2+33)); const nh=md(hue+ (n*40-40),360);
      for(let k=4;k>=1;k--){ g.fill(nh,40,60,3*k/4); g.ellipse(nx,ny,nr*k*0.5,nr*k*0.42);} }
  }
  S.bg=g;
}

const stars=S.stars, segs=S.segs, cons=S.cons, nseg=S.nseg;

// ---- global slow sky rotation (real-time motion floor for ALL styles) ----
const wheel=P.act==='wheel';
const rot=K.t*(wheel?0.02:0.005)*spd;
const cxp=P.x*W, cyp=P.y*Hh, cs=Math.cos(rot), sn=Math.sin(rot);
function proj(nx,ny){ const px=(nx-P.x)*W, py=(ny-P.y)*Hh; return [cxp+px*cs-py*sn, cyp+px*sn+py*cs]; }

image(S.bg,0,0);

// ---- constellation reveal progress: continuously cycles (guarantees 8s diff) ----
const revRate=(P.act==='storm')?0.10:0.055;
const rev=md(K.t*revRate*spd + K.section*0.13, 1);   // 0..1 sweep across all segments
const litCon=Math.floor(rev*Math.max(1,cons.length));

// draw hinted mythic figure behind the currently-lit constellation
if(cons.length){
  const cc=cons[md(litCon,cons.length)];
  const [fx,fy]=proj(cc.cx,cc.cy); const fr2=cc.r*Math.min(W,Hh)*1.4;
  const figA=en*(0.5+0.5*K.swell)*ez((rev*cons.length)%1);
  if(figA>0.02 && !blue){
    push(); translate(fx,fy);
    const fh=parch?32:md(hue+30,360), fs=parch?45:40, fb=parch?35:70;
    noFill(); stroke(fh,fs,fb, (parch?22:16)*figA); strokeWeight(u*0.004*clp(P.scale,.5,2));
    beginShape();
    for(let a=0;a<=10;a++){ const an=a/10*TAU; const rr=fr2*(0.5+0.35*Math.sin(an*3+cc.cx*9)+0.2*Math.cos(an*2+P.seed)); vertex(Math.cos(an)*rr,Math.sin(an)*rr*0.8);}
    endShape(CLOSE); pop();
  }
}

// ---- constellation lines drawing in ----
const lineH = night? md(hue+6,360) : spec? md(hue+10,360) : parch? 30 : 195;
const lineS = parch?55: blue?55: 45;
const lineB = parch?38: 92;
strokeCap(ROUND);
for(let s=0;s<nseg;s++){
  const seg=segs[s]; const t0=s/Math.max(1,nseg);
  // reveal window for this segment
  const w=clp((rev - t0)*Math.max(4,nseg*0.5),0,1);
  if(w<=0) continue;
  const A0=stars[seg.a], B0=stars[seg.b];
  const [ax,ay]=proj(A0.x,A0.y), [bx,by]=proj(B0.x,B0.y);
  const ex=ax+(bx-ax)*ez(w), ey=ay+(by-ay)*ez(w);
  const active=Math.abs(seg.c-litCon)<1;
  const gl=active? (0.7+0.6*K.pulse+0.7*A.mid) : 0.35;
  stroke(lineH,lineS, lineB, (parch?70:38)*gl*(0.5+0.7*en));
  strokeWeight(u*(active?0.0028:0.0016)*clp(P.scale,.5,2.2));
  if(blue){ // schematic dashed vector
    const dl=Math.hypot(ex-ax,ey-ay), n=Math.max(2,Math.floor(dl/8));
    for(let d=0;d<n;d+=2){ const u0=d/n,u1=Math.min(1,(d+1)/n); line(ax+(ex-ax)*u0,ay+(ey-ay)*u0, ax+(ex-ax)*u1,ay+(ey-ay)*u1);} }
  else line(ax,ay,ex,ey);
}

// ---- stars (twinkle = continuous real-time motion) ----
noStroke();
const twGlobal=0.6+0.8*en;
for(let s=0;s<stars.length;s++){
  const st=stars[s]; const [x,y]=proj(st.x,st.y);
  if(x< -4||x>W+4||y<-4||y>Hh+4) continue;
  const tw=night||spec? (0.6+0.4*Math.sin(K.t*st.tr*spd+st.tp)) : (0.8+0.2*Math.sin(K.t*st.tr*0.5+st.tp));
  const b=clp(st.b*tw*twGlobal,0,100);
  const sz=st.sz*u*0.0032*clp(P.scale,.5,2.2)*(0.8+0.5*tw);
  if(spec){ const c=temp(st.tmp); noStroke(); fill(c[0],c[1]*0.9,clp(b,10,100)); circle(x,y,sz*1.2); }
  else if(parch){ // engraved ink star: cross tick
    stroke(30,60,28,clp(b,20,90)); strokeWeight(u*0.0016); const r=sz*1.3;
    line(x-r,y,x+r,y); line(x,y-r,x,y+r); noStroke(); if(st.mag<0.15){fill(30,60,26,b);circle(x,y,sz*0.9);} }
  else if(blue){ // ring marker
    stroke(195,45,95,clp(b,15,80)); strokeWeight(u*0.0013); noFill(); circle(x,y,sz*2.0);
    if(st.mag<0.1){noStroke();fill(195,30,100,b);circle(x,y,sz*0.9);} noStroke(); }
  else { // night: white-blue glow dot, shadowBlur only on the brightest
    if(st.mag<0.12){ drawingContext.shadowBlur=sz*3.5; drawingContext.shadowColor='rgba(180,210,255,0.9)'; }
    fill(md(hue+ (st.mag<0.3?0:8),360), st.mag<0.2?18:8, b); circle(x,y,sz); drawingContext.shadowBlur=0; }
}
drawingContext.shadowBlur=0;

// ---- rare shooting star (real-time schedule; frequent in 'storm') ----
const period=P.act==='storm'?3.5:11.0;
const ph=md(K.t/period + fr(99.1), 1);
if(ph<0.12){
  const k=ph/0.12; const seedi=Math.floor(K.t/period);
  const sx=fr(seedi*3.7+41)*W, sy=fr(seedi*1.9+42)*Hh*0.5;
  const ang=(-0.35+0.7*fr(seedi*5.3+43))+Math.PI*0.15;
  const len=u*0.22; const hx=sx+Math.cos(ang)*len*k, hy=sy+Math.sin(ang)*len*k;
  const tx=hx-Math.cos(ang)*len*0.5, ty=hy-Math.sin(ang)*len*0.5;
  const fade=Math.sin(k*Math.PI);
  blendMode(ADD);
  stroke(md(hue+20,360),20,100,70*fade); strokeWeight(u*0.003); line(tx,ty,hx,hy);
  noStroke(); fill(0,0,100,90*fade); circle(hx,hy,u*0.01*(0.5+fade));
  blendMode(BLEND);
}
drawingContext.shadowBlur=0;
blendMode(BLEND);
